connection(name = this.getDefaultConnectionName()) {
    const existing = this.connections.get(name);
    if (existing) {
        return existing;
    }
    const connectionConfig = this.config.connections[name];
    if (!connectionConfig) {
        throw new Error(`Database connection "${name}" is not configured.`);
    }
    const resolvedConnectionConfig = {
        ...connectionConfig,
        databaseDriver: resolveDatabaseDriver(connectionConfig, this.config.drivers, name),
    };
    const metadataStore = resolveMetadataStore(resolvedConnectionConfig.metadataStore ?? this.config.metadataStore);
    if (resolvedConnectionConfig.schemaManagement === 'external' &&
        !metadataStore) {
        throw new CollectionMetadataStoreRequiredError(name);
    }
    const connection = this.factory.create({
        name,
        config: resolvedConnectionConfig,
        metadataStore,
    });
    this.connections.set(name, connection);
    return connection;
}
